export interface DbExecuteResult {
    changes: number;
    lastInsertRowid: number;
}

export interface DbDriver {
    query<T>(sql: string, ...params: unknown[]): Promise<T[]>;
    execute(sql: string, ...params: unknown[]): Promise<DbExecuteResult>;
    
    /**
     * Type-safe overloads for queryOne:
     * 1. Without options -> Returns T | null
     * 2. With notFound handler -> Returns T (narrowed, as it will throw if missing)
     * This is the idiomatic TypeScript way to narrow return types based on argument presence.
     */
    queryOne<T>(sql: string, params?: unknown[]): Promise<T | null>;
    queryOne<T>(sql: string, params: unknown[], options: { notFound: () => Error }): Promise<T>;
}

/**
 * Story 388 — row types declare a nullable column as `T | null`, which is what both engines return.
 * A create/patch payload built from a row (`NewX`) may leave those columns out: this makes every key
 * whose type admits `null` optional, and leaves the rest required.
 */
type NullableKeys<T> = { [K in keyof T]-?: null extends T[K] ? K : never }[keyof T];
export type OptionalNullables<T> = Omit<T, NullableKeys<T>> & Partial<Pick<T, NullableKeys<T>>>;

/** What both engines bind the same way. */
export type DbBindValue = null | number | bigint | string | Uint8Array;

function transactionKindOf(sql: string): 'BEGIN' | 'END' | null {
    const match = /^\s*(BEGIN|COMMIT|ROLLBACK|END)\b/i.exec(sql);
    if (!match) return null;
    return match[1].toUpperCase() === 'BEGIN' ? 'BEGIN' : 'END';
}

export abstract class BaseDbDriver implements DbDriver {
    abstract query<T>(sql: string, ...params: unknown[]): Promise<T[]>;
    abstract execute(sql: string, ...params: unknown[]): Promise<DbExecuteResult>;

    /**
     * Story 388 — every engine driver passes its parameters through here before binding. node:sqlite
     * read a leading `{}` as the named-parameter bag (a silent 0-row UPDATE) and threw on undefined;
     * sqlite-wasm threw on an object and bound undefined as NULL. Anything but the five types both
     * engines agree on is a TypeError naming its 1-based position, on either runtime.
     */
    protected bindable(params: unknown[]): DbBindValue[] {
        params.forEach((value, index) => {
            const ok = value === null || typeof value === 'number' || typeof value === 'bigint'
                || typeof value === 'string' || value instanceof Uint8Array;
            if (!ok) {
                const kind = value === undefined ? 'undefined' : typeof value === 'object' ? value.constructor?.name ?? 'object' : typeof value;
                throw new TypeError(`DbDriver: parameter ${index + 1} is ${kind}; only null, number, bigint, string and Uint8Array bind.`);
            }
        });
        return params as DbBindValue[];
    }

    private inTransaction = false;
    private transactionTurn: Promise<void> = Promise.resolve();
    private endTransactionTurn: (() => void) | null = null;

    /**
     * Story 361 — one transaction at a time per driver. Every caller shares the driver and
     * interleaves at each await, so a BEGIN waits until the open transaction has ended instead of
     * colliding with it (DLR #46's "nothing races" was false on both runtimes: concurrent offline
     * requests, and concurrent server requests). COMMIT / ROLLBACK hand the turn on; a BEGIN that
     * fails hands it straight back. Statements outside a transaction are not held back. A
     * transaction must never start another — it would wait on itself.
     */
    protected async inTransactionTurn<T>(sql: string, run: () => Promise<T>): Promise<T> {
        const kind = transactionKindOf(sql);
        let release: () => void = () => {};
        if (kind === 'BEGIN') {
            const previous = this.transactionTurn;
            this.transactionTurn = new Promise<void>((resolve) => {
                release = resolve;
            });
            await previous;
        }
        if (kind === 'END' && !this.inTransaction) {
            throw new Error(`DbDriver: ${sql.trim().split(/\s+/)[0].toUpperCase()} issued without an open transaction on this driver. See DLR #46.`);
        }
        try {
            const result = await run();
            if (kind === 'BEGIN') {
                this.inTransaction = true;
                this.endTransactionTurn = release;
            } else if (kind === 'END') {
                this.inTransaction = false;
                const handOn = this.endTransactionTurn;
                this.endTransactionTurn = null;
                handOn?.();
            }
            return result;
        } catch (err) {
            if (kind === 'BEGIN') release();
            throw err;
        }
    }

    /**
     * Catches double-BEGIN and orphan COMMIT/ROLLBACK on this driver instance.
     * See DLR #46 — does NOT catch interleaved statements from other callers
     * during a transaction's await window; that invariant is held by the caller.
     */
    protected checkTransactionPrecondition(sql: string): 'BEGIN' | 'END' | null {
        const match = /^\s*(BEGIN|COMMIT|ROLLBACK|END)\b/i.exec(sql);
        if (!match) return null;
        const kind = match[1].toUpperCase() === 'BEGIN' ? 'BEGIN' : 'END';
        if (kind === 'BEGIN' && this.inTransaction) {
            throw new Error(
                'DbDriver: BEGIN issued while a transaction is already open on this driver. ' +
                    'Multi-step transactions on a shared driver are not safe across awaits — see DLR #46.',
            );
        }
        if (kind === 'END' && !this.inTransaction) {
            throw new Error(
                `DbDriver: ${match[1].toUpperCase()} issued without an open transaction on this driver. See DLR #46.`,
            );
        }
        return kind;
    }

    protected markTransactionState(kind: 'BEGIN' | 'END' | null): void {
        if (kind === 'BEGIN') this.inTransaction = true;
        else if (kind === 'END') this.inTransaction = false;
    }

    async queryOne<T>(sql: string, params?: unknown[]): Promise<T | null>;
    async queryOne<T>(sql: string, params: unknown[], options: { notFound: () => Error }): Promise<T>;
    async queryOne<T>(
        sql: string,
        params: unknown[] = [],
        options: { notFound?: () => Error } = {},
    ): Promise<T | null> {
        const rows = await this.query<T>(sql, ...params);

        if (rows.length > 1) {
            throw new Error(`Expected at most 1 row, got ${rows.length} for query: ${sql}`);
        }

        if (rows.length === 0) {
            if (options.notFound) throw options.notFound();
            return null;
        }

        return rows[0];
    }
}
